const today = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Kolkata',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).format(new Date());

const executedAtIST = new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Asia/Kolkata',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false,
}).format(new Date()) + ' IST';

function toUtcMs(isoDate) {
  if (!isoDate || !/^\d{4}-\d{2}-\d{2}$/.test(String(isoDate).trim())) return null;
  const [y, m, d] = String(isoDate).trim().split('-').map(Number);
  return Date.UTC(y, m - 1, d);
}

const todayMs = toUtcMs(today);
const rows = $input.all().map((i) => i.json).filter((r) => r && r.member_id);

const active = [];
const expiring7d = [];
const expired = [];
const pending = [];
const newSignupsToday = [];
let pendingAmount = 0;
let collectionsToday = 0;

for (const r of rows) {
  const expStr = String(r.expiry_date || '').trim();
  const expMs = toUtcMs(expStr);
  const daysLeft = expMs !== null ? Math.round((expMs - todayMs) / 86400000) : null;
  const feeNum = Number(r.fee || 0) || 0;

  if (expStr >= today && String(r.member_status || '') !== 'Frozen') {
    active.push(r);
  }
  if (daysLeft !== null && daysLeft >= 0 && daysLeft <= 7) {
    expiring7d.push(r);
  }
  if (expStr && expStr < today) {
    expired.push(r);
  }
  if (String(r.payment_status || '').trim() === 'Pending') {
    pending.push(r);
    pendingAmount += feeNum;
  }
  if (String(r.start_date || '').trim() === today) {
    newSignupsToday.push(r);
  }
  if (String(r.last_payment_date || '').trim() === today && String(r.payment_status || '').trim() === 'Paid') {
    collectionsToday += feeNum;
  }
}

const followupCandidates = [...expiring7d, ...pending].map((r) => `${r.name} (${r.member_id})`).slice(0, 10);
const summaryText =
  `Crush Lifestyle Fitness Studio - Daily Owner Digest (${today})\n` +
  `Total Members: ${rows.length}\n` +
  `Active: ${active.length} | Expiring <=7d: ${expiring7d.length} | Expired: ${expired.length}\n` +
  `New Signups Today: ${newSignupsToday.length} | Collections Today: Rs.${collectionsToday}\n` +
  `Pending Dues: ${pending.length} (Rs.${pendingAmount})\n` +
  `Priority Follow-Ups: ${followupCandidates.length ? followupCandidates.join(', ') : 'None'}`;

return [{
  json: {
    log_id: `DIGEST-${today.replace(/-/g, '')}`,
    timestamp: executedAtIST,
    date: today,
    total_members: rows.length,
    active_count: active.length,
    expiring_in_7_days_count: expiring7d.length,
    expired_count: expired.length,
    pending_dues_count: pending.length,
    pending_dues_amount: pendingAmount,
    new_signups_today_count: newSignupsToday.length,
    collections_today_amount: collectionsToday,
    followup_candidates: followupCandidates,
    summary_text: summaryText,
  },
}];
